func testGradeProdutoToManyRemoveOpGradeProdutos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a GradeProduto
	var b, c, d, e Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, gradeProdutoDBTypes, false, strmangle.SetComplement(gradeProdutoPrimaryKeyColumns, gradeProdutoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Produto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddGradeProdutos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.GradeProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveGradeProdutos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.GradeProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.GradeID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.GradeID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Grade != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Grade != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Grade != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Grade != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.GradeProdutos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.GradeProdutos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.GradeProdutos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

func testGradeProdutoToOneEmpresaFilialUsingEmf(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local GradeProduto
	var foreign EmpresaFilial

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, gradeProdutoDBTypes, false, gradeProdutoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize GradeProduto struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, empresaFilialDBTypes, false, empresaFilialColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize EmpresaFilial struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.EmfID = foreign.EmfID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Emf().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.EmfID != foreign.EmfID {
		t.Errorf("want: %v, got %v", foreign.EmfID, check.EmfID)
	}

	ranAfterSelectHook := false
	AddEmpresaFilialHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *EmpresaFilial) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := GradeProdutoSlice{&local}
	if err = local.L.LoadEmf(ctx, tx, false, (*[]*GradeProduto)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Emf = nil
	if err = local.L.LoadEmf(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

